    "statement": "被相続人の占有を併せて主張する場合には、相続人が占有を始めた時に悪意であっても、善意と判定されます。",
    "context": "【原問の対話：先行する発言には誤った解答も含まれます】\n第７問       次の対話は、占有に関する教授と学生との対話である。教授の質問に対する次のアか\n   らオまでの学生の解答のうち、判例の趣旨に照らし正しいものの組合せは、後記 １ から\n      ５ までのうち、どれか。\n      教授：      今日は、占有者の善意・悪意について考えてみましょう。占有者については、\n            占有の態様等に関して、どのような推定がされますか。\n      学生：ア 占有者は、所有の意思をもって、平穏に、かつ、公然と占有をするものと推\n               定されますが、占有者が善意であることは推定されません。\n      教授：      占有物から生ずる果実の収取について考えてみましょう。悪意の占有者は、果\n            実の収取を怠った場合には、その果実の代価を償還する義務を負いますか。\n      学生：イ      収取を怠った果実の代価を償還する義務を負いません。\n      教授：      占有物が占有者の責めに帰すべき事由によって滅失し、又は損傷したときにお\n            ける占有者の損害賠償の範囲について考えてみましょう。所有の意思のない善意\n            の占有者は、どの範囲で賠償する義務を負いますか。\n      学生：ウ      損害の全部の賠償をする義務を負います。\n      教授：      善意の占有者が本権の訴えにおいて敗訴したときは、いつから悪意の占有者と\n            みなされますか。\n      学生：エ      占有を始めた時にさかのぼって悪意の占有者とみなされます。\n      教授：      相続が発生した場合の取得時効についても考えてみましょう。相続人である占\n            有者は、その選択に従い、被相続人の占有に自己の占有を併せて主張することも\n            できます。では、占有を始めた時に悪意であった相続人が占有を始めた時に善意\n            であった被相続人を相続した場合において、その相続人が被相続人の占有を併せ\n            て主張するときは、取得時効の要件としての占有者の善意・悪意は、どのように\n            判定されますか。",
